  // ============ Merge ============
  public static Herald.Config.Builder mergeConfig(Herald.Config dst, Herald.Config src) {
    Herald.Config.Builder builder = dst.toBuilder();
    if (dst.getVisibleEventTypesList().isEmpty()) {
      builder.addAllVisibleEventTypes(src.getVisibleEventTypesList());
    }
    if (dst.getMaxSubscribers() == 0) {
      builder.setMaxSubscribers(src.getMaxSubscribers());
    }
    return builder;
  }

  public static Herald.PublishEventsResponse.Builder mergePublishEventsResponse(
      Herald.PublishEventsResponse dst, Herald.PublishEventsResponse src) {
    Herald.PublishEventsResponse.Builder builder = dst.toBuilder();
    if (dst.getEventsAccepted() == 0) {
      builder.setEventsAccepted(src.getEventsAccepted());
    }
    return builder;
  }

  public static Herald.SubscribeEventsRequest.Builder mergeSubscribeEventsRequest(
      Herald.SubscribeEventsRequest dst, Herald.SubscribeEventsRequest src) {
    Herald.SubscribeEventsRequest.Builder builder = dst.toBuilder();
    if (dst.getEventTypeValue() == 0) {
      builder.setEventTypeValue(src.getEventTypeValue());
    }
    if (dst.getSensorTypeValue() == 0) {
      builder.setSensorTypeValue(src.getSensorTypeValue());
    }
    if (dst.getSessionId().isEmpty()) {
      builder.setSessionId(src.getSessionId());
    }
    return builder;
  }

  public static Herald.HeraldConfigState.Builder mergeHeraldConfigState(
      Herald.HeraldConfigState dst, Herald.HeraldConfigState src) {
    Herald.HeraldConfigState.Builder builder = dst.toBuilder();
    if (!dst.hasConfig() && src.hasConfig()) {
      builder.setConfig(src.getConfig());
    } else if (dst.hasConfig() && src.hasConfig()) {
      builder.setConfig(mergeConfig(dst.getConfig(), src.getConfig()).build());
    }
    return builder;
  }

  // ============ EnvVar ============
  public static Map<String, String> configToEnvVar(Herald.Config msg) {
    Map<String, String> result = new HashMap<>();
    if (!msg.getVisibleEventTypesList().isEmpty()) {
      result.put(
          "PROTO_CONFIG_VISIBLE_EVENT_TYPES",
          msg.getVisibleEventTypesList().stream()
              .map(
                  v ->
                      com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.types.common
                          .sensor.Helpers.sensorEventTypeToString(v))
              .collect(Collectors.joining(",")));
    }
    result.put("PROTO_CONFIG_MAX_SUBSCRIBERS", String.valueOf(msg.getMaxSubscribers()));
    return result;
  }

  public static Herald.Config.Builder configFromEnvVar(Map<String, String> env) {
    Herald.Config.Builder builder = Herald.Config.newBuilder();
    String val;
    val = env.get("PROTO_CONFIG_VISIBLE_EVENT_TYPES");
    if (val != null && !val.isEmpty()) {
      for (String part : val.split(",")) {
        builder.addAllVisibleEventTypes(
            java.util.Collections.singletonList(
                com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.types.common.sensor
                    .Helpers.parseSensorEventType(part.trim())));
      }
    }
    val = env.get("PROTO_CONFIG_MAX_SUBSCRIBERS");
    if (val != null && !val.isEmpty()) {
      builder.setMaxSubscribers(Integer.parseInt(val));
    }
    return builder;
  }

